2903	static bool ContainsCompileOrAssembleAction(const Action *A) {
2904	  if (isa<CompileJobAction>(A) || isa<BackendJobAction>(A) ||
2905	      isa<AssembleJobAction>(A))
2906	    return true;
2907	
2908	  return llvm::any_of(A->inputs(), ContainsCompileOrAssembleAction);
2909	}
