    } else {
      NewDAL = TC->TranslateXarchArgs(*OpenMPArgs, BA, DeviceOffloadKind,
                                      &AllocatedArgs);
      if (!NewDAL)
        NewDAL = OpenMPArgs;
      else
  llvm::cl::ExpansionContext ECtx(A, llvm::cl::TokenizeGNUCommandLine,
