  const OptTable &Opts = getDriver().getOpts();

  if (DeviceOffloadKind == Action::OFK_None) {
    // AMDGPU is intended to use `-mcpu` but we accept `-march` for legacy.
    if (Arg *A = DAL->getLastArg(options::OPT_march_EQ)) {
